response:
**Gates before launch**

I run five gates before I launch. First, I check git to confirm that spe/predictions/r04.yaml and spe/plans/r04.md are committed and have no local edits. Second, I run the grade.py selftest. The oracle answers must pass, and the empty and wrong answers must fail. I also give the judge one known-good reply and one known-bad reply, and I check that it scores them apart. Third, I regrade round 3's saved results with this round's grader and judge. This is the control. If its numbers differ from what round 3 logged, the grader changed, so I stop and find the cause. Fourth, I diff this script against r03-workflow.js. The round number may appear only in the ROUND argument. Fifth, I do a dry run with `only` set to 3 cells across both configs and `trialsPerCell: 1`. I check that every result matches its schema, and I replace `estTrialUsd` with the measured cost per trial. When all five gates pass, I commit `SPE r04 evaluate (harness): ...` and start the full run.

I did not read r03's script, so some parts below are guesses. These are the runner command, its flags, the meta.json fields, and the grade.py CLI. I will match them to r03 before the dry run. The script checks the $40 cap against measured spend by the configs under test plus estimated judge spend. It caps harness agents with a separate `maxAgents` limit. All cost figures in it are unmeasured estimates until the dry run.

```js
export const meta = {
  name: 'spe-evaluate',
  description: 'SPE evaluate step. Runs each config on every support ticket, grades labels with grade.py, judges reply tone blind with Opus, and keeps spend and agent count under caps from args.',
  phases: [
    { title: 'Preflight', description: 'Check the prediction is committed, run the grader selftest, list tickets' },
    { title: 'Trials', description: 'Run each config on each ticket, then code-grade each cell' },
    { title: 'Top-up', description: 'Extra trials for cells where only some trials passed' },
    { title: 'Judge', description: 'Blind Opus tone judge on shuffled replies' },
    { title: 'Synthesis', description: 'Aggregate metrics, failure analysis, completeness critic, write results' },
  ],
}

// ---------- arguments ----------
const A = typeof args === 'object' && args !== null ? args : {}
const ROUND = Number(A.round ?? 4)
const RR = String(ROUND).padStart(2, '0')
const CONFIGS = A.configs ?? ['B', 'C2']
const TRIALS = Number(A.trialsPerCell ?? 5)
const EXPECTED_TICKETS = Number(A.expectedTickets ?? 50)
const TOPUP_MAX = Number(A.topUpMax ?? 5)
const ONLY = Array.isArray(A.only) ? A.only : null
const RUNNER = A.runnerCmd ?? 'python spe/evals/harness/run_trial.py' // match r03
const MODEL = A.harnessModel ?? 'opus'
const JUDGE_MODEL = A.judgeModel ?? 'opus'
const JUDGE_BATCH = Number(A.judgeBatch ?? 10)
const MAX_GRADER_ERRORS = Number(A.maxGraderErrors ?? 3)
const SEED = Number(A.seed ?? 1234)
const SALT = String(A.blindSalt ?? `blind-r${RR}-${SEED}`)

// Paid resources and their caps. Estimates are unmeasured until the dry run.
const CAP_USD = Number(A.spendCapUsd ?? 40)
const SYNTH_RESERVE_USD = Number(A.synthesisReserveUsd ?? 1)
const MAX_AGENTS = Number(A.maxAgents ?? 450)
const EST_TRIAL_USD = Number(A.estTrialUsd ?? 0.04)
const EST_JUDGE_BATCH_USD = Number(A.estJudgeBatchUsd ?? 0.3)

const P = {
  results: `spe/evals/results/r${RR}`,
  grader: 'spe/evals/graders/grade.py',
  answers: 'spe/evals/tasks/answers.json',
  judge: 'spe/evals/graders/judge.md',
  tasks: 'spe/evals/tasks',
  prediction: `spe/predictions/r${RR}.yaml`,
  plan: `spe/plans/r${RR}.md`,
}
const FORBIDDEN = ['spe/evals/', 'spe/predictions/', 'spe/plans/', 'spe/spec/', 'spe/prediction-log.md', 'spe/failures.md']

// ---------- helpers ----------
const range = (a, b) => Array.from({ length: Math.max(0, b - a) }, (_, i) => a + i)
const sum = xs => xs.reduce((s, x) => s + (Number(x) || 0), 0)
const mean = xs => (xs.length ? sum(xs) / xs.length : null)
const median = xs => {
  if (!xs.length) return null
  const s = [...xs].sort((a, b) => a - b)
  const m = Math.floor(s.length / 2)
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2
}
const r3 = x => (x == null ? null : Math.round(x * 1000) / 1000)
function fnv(str) {
  let h = 0x811c9dc5
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i)
    h = Math.imul(h, 0x01000193) >>> 0
  }
  return h.toString(16).padStart(8, '0')
}
const blindId = (cfg, ticket, trial) =>
  'x' + fnv(`${SALT}|${cfg}|${ticket}|${trial}`) + fnv(`${trial}|${ticket}|${cfg}|${SALT}`)
function rng(seed) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6d2b79f5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}
function shuffle(xs, seed) {
  const r = rng(seed)
  const out = [...xs]
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(r() * (i + 1))
    const tmp = out[i]
    out[i] = out[j]
    out[j] = tmp
  }
  return out
}

// ---------- budget and halt state ----------
const state = { halted: null, graderErrors: 0, agents: 0, skipped: [], voids: [] }
const budget = { cap: CAP_USD, spent: 0, reserved: 0, measured: 0, estimated: 0 }

function halt(reason) {
  if (!state.halted) {
    state.halted = reason
    log(`HALT round ${ROUND}: ${reason}. No new trials or judge calls start. Synthesis still runs and reports.`)
  }
}
function canStartAgent(kind, id) {
  if (state.agents + 1 > MAX_AGENTS) {
    state.skipped.push({ kind, id, reason: `agent cap ${MAX_AGENTS}` })
    log(`Skip ${kind} ${id}: agent cap ${MAX_AGENTS} reached`)
    halt('agent cap reached')
    return false
  }
  state.agents += 1
  return true
}
function reserve(kind, estUsd, id) {
  if (state.halted) {
    state.skipped.push({ kind, id, reason: `halted: ${state.halted}` })
    return false
  }
  const limit = budget.cap - SYNTH_RESERVE_USD
  if (budget.spent + budget.reserved + estUsd > limit) {
    state.skipped.push({ kind, id, est_usd: estUsd, reason: 'spend cap' })
    log(`Skip ${kind} ${id}: would cross $${limit.toFixed(2)} (spent ${budget.spent.toFixed(2)}, reserved ${budget.reserved.toFixed(2)}, est ${estUsd.toFixed(2)})`)
    halt('spend cap reached')
    return false
  }
  if (!canStartAgent(kind, id)) return false
  budget.reserved += estUsd
  return true
}
function settle(estUsd, measuredUsd, estimatedUsd) {
  budget.reserved -= estUsd
  budget.spent += measuredUsd + estimatedUsd
  budget.measured += measuredUsd
  budget.estimated += estimatedUsd
}

// ---------- schemas ----------
const PREFLIGHT_SCHEMA = {
  type: 'object',
  required: ['prediction_committed', 'selftest_ok', 'ticket_ids', 'runner_ok'],
  properties: {
    prediction_committed: { type: 'boolean' },
    prediction_detail: { type: 'string' },
    selftest_ok: { type: 'boolean' },
    selftest_detail: { type: 'string' },
    runner_ok: { type: 'boolean' },
    runner_detail: { type: 'string' },
    ticket_ids: { type: 'array', items: { type: 'string' } },
  },
}
const RUN_SCHEMA = {
  type: 'object',
  required: ['trials'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'status'],
        properties: {
          trial: { type: 'integer' },
          status: { type: 'string', enum: ['completed', 'harness_error', 'rate_limited'] },
          out_dir: { type: 'string' },
          transcript_path: { type: 'string' },
          runtime_s: { type: 'number' },
          tool_calls: { type: 'integer' },
          tool_errors: { type: 'integer' },
          input_tokens: { type: 'integer' },
          output_tokens: { type: 'integer' },
          cost_usd: { type: 'number' },
          error: { type: 'string' },
        },
      },
    },
  },
}
const GRADE_SCHEMA = {
  type: 'object',
  required: ['results'],
  properties: {
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'grader_error', 'peeked', 'blind_written'],
        properties: {
          trial: { type: 'integer' },
          category_ok: { type: 'boolean' },
          priority_ok: { type: 'boolean' },
          grader_error: { type: 'boolean' },
          grader_error_detail: { type: 'string' },
          peeked: { type: 'boolean' },
          peek_evidence: { type: 'string' },
          blind_written: { type: 'boolean' },
        },
      },
    },
  },
}
const JUDGE_SCHEMA = {
  type: 'object',
  required: ['items'],
  properties: {
    items: {
      type: 'array',
      items: {
        type: 'object',
        required: ['blind_id', 'tone_score', 'tone_pass'],
        properties: {
          blind_id: { type: 'string' },
          tone_score: { type: 'number' },
          tone_pass: { type: 'boolean' },
          reason: { type: 'string' },
        },
      },
    },
  },
}
const FAILURE_SCHEMA = {
  type: 'object',
  required: ['modes'],
  properties: {
    modes: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'title', 'count'],
        properties: {
          id: { type: 'string' },
          title: { type: 'string' },
          configs: { type: 'array', items: { type: 'string' } },
          count: { type: 'integer' },
          example_trials: { type: 'array', items: { type: 'string' } },
          likely_cause: { type: 'string' },
        },
      },
    },
    notes: { type: 'string' },
  },
}
const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: {
    complete: { type: 'boolean' },
    gaps: { type: 'array', items: { type: 'string' } },
    notes: { type: 'string' },
  },
}

// ---------- Preflight ----------
phase('Preflight')
const pre = await agent(
  `You run preflight checks for SPE round ${ROUND}. Report facts only.
1. Run \`git log --oneline -5 -- ${P.prediction} ${P.plan}\` and \`git status --porcelain -- ${P.prediction} ${P.plan}\`. prediction_committed is true only if both files are in a commit and have no local changes.
2. Run the selftest for ${P.grader} the way its --help describes. selftest_ok is true only if the oracle answers pass and the empty and wrong answers fail. Quote the output lines in selftest_detail.
3. Run \`${RUNNER} --help\`. runner_ok is true if it prints usage that accepts --config, --ticket, --trial, and --out.
4. List the ticket ids from the ticket file in ${P.tasks}/. Do not include answers.json content in your reply. Return the ids in file order.`,
  { label: 'preflight', phase: 'Preflight', schema: PREFLIGHT_SCHEMA, model: MODEL }
)
state.agents += 1
if (!pre || !pre.prediction_committed) throw new Error(`Stop: ${P.prediction} is not committed. Write it first. ${pre?.prediction_detail ?? ''}`)
if (!pre.selftest_ok) throw new Error(`Stop: grader selftest failed. ${pre.selftest_detail ?? ''}`)
if (!pre.runner_ok) throw new Error(`Stop: runner check failed. ${pre.runner_detail ?? ''}`)
const tickets = pre.ticket_ids ?? []
if (!ONLY && tickets.length !== EXPECTED_TICKETS) {
  throw new Error(`Stop: expected ${EXPECTED_TICKETS} tickets, found ${tickets.length}`)
}

let cells = []
for (const cfg of CONFIGS) for (const ticket of tickets) cells.push({ id: `${cfg}:${ticket}`, cfg, ticket })
if (ONLY) {
  cells = cells.filter(c => ONLY.includes(c.id))
  log(`Dry run: ${cells.length} cells from args.only`)
}
log(`Round ${ROUND}: ${cells.length} cells x ${TRIALS} trials = ${cells.length * TRIALS} planned trials. Spend cap $${CAP_USD}. Agent cap ${MAX_AGENTS}. Estimated trial spend $${(cells.length * TRIALS * EST_TRIAL_USD).toFixed(2)} (unmeasured).`)

// ---------- trial and grade stages ----------
async function runCell(cell, start, n, phaseTitle) {
  const nums = range(start, start + n)
  const id = `${cell.id}#${start}-${start + n - 1}`
  const est = n * EST_TRIAL_USD
  if (!reserve('trials', est, id)) {
    return nums.map(trial => ({ cfg: cell.cfg, ticket: cell.ticket, trial, status: 'skipped' }))
  }
  const outBase = `${P.results}/raw/${cell.cfg}/${cell.ticket}`
  const res = await agent(
    `You are a trial runner for SPE round ${ROUND}. You start a support-ticket agent and report what it did. You are not the agent under test, and you do not judge its work.

Run these commands from the repo root, one at a time, in order:
${nums.map(t => `  ${RUNNER} --config ${cell.cfg} --ticket ${cell.ticket} --trial ${t} --out ${outBase}/t${t}`).join('\n')}

After each command, read ${outBase}/t<N>/meta.json for that trial and copy its fields into your result.

Rules:
- Run only the commands above. Read only the meta.json files named above.
- Do not open, list, grep, or cat any other file. Never touch ${FORBIDDEN.join(', ')} except the meta.json files above.
- If a command crashes, a file is missing, or a flag is rejected, set status "harness_error" and put the first error line in error.
- If a command fails with HTTP 429 or a rate limit message, wait 30 seconds and retry it once. If it fails again, set status "rate_limited".
- Do not rerun a trial because the agent's answer looks wrong. A wrong answer is a completed trial.
- Report every trial number listed, including failed ones.`,
    { label: `run ${id}`, phase: phaseTitle, schema: RUN_SCHEMA, model: MODEL }
  )
  const got = new Map((res?.trials ?? []).map(t => [t.trial, t]))
  const rows = nums.map(trial => {
    const t = got.get(trial) ?? { trial, status: 'harness_error', error: 'runner agent returned no row' }
    return { ...t, cfg: cell.cfg, ticket: cell.ticket, trial }
  })
  settle(est, sum(rows.map(r => r.cost_usd)), 0)
  return rows
}

async function gradeCell(cell, rows, phaseTitle, tag) {
  const done = rows.filter(r => r.status === 'completed')
  if (!done.length) return rows
  if (!canStartAgent('grade', `${cell.id}#${tag}`)) {
    return rows.map(r => (r.status === 'completed' ? { ...r, graded: false, ungraded_reason: 'agent cap' } : r))
  }
  const res = await agent(
    `You grade SPE round ${ROUND} cell ${cell.id}. The config is ${cell.cfg} and the ticket is ${cell.ticket}. Use the code grader. Do not grade by hand.

Trials:
${done.map(r => `- trial ${r.trial}: out_dir=${r.out_dir}, transcript=${r.transcript_path}, blind_id=${blindId(cell.cfg, cell.ticket, r.trial)}`).join('\n')}

Steps:
1. For each trial, run ${P.grader} against ${P.answers} and that trial's output, using the CLI that grade.py documents in --help. Copy category_ok and priority_ok exactly as the grader reports them. If the grader crashes or its output is unclear, set grader_error true and quote the error. Do not guess.
2. Scan each trial's transcript for any read, open, list, grep, or tool argument that names one of these paths: ${FORBIDDEN.join(', ')}. Also flag any text that quotes answers.json. If you find one, set peeked true and quote the line in peek_evidence.
3. For each trial, write ${P.results}/blind/<blind_id>.md. Copy the ticket text from the ticket file in ${P.tasks}/ under "## Ticket". Copy the agent's customer reply from out_dir under "## Reply". Leave out the config name, trial number, labels, tool names, and anything else that tells the configs apart. Set blind_written true when the file exists.
4. Write your results as JSON to ${P.results}/cells/${cell.cfg}__${cell.ticket}__${tag}.json and return the same results.`,
    { label: `grade ${cell.id} ${tag}`, phase: phaseTitle, schema: GRADE_SCHEMA, model: MODEL }
  )
  const g = new Map((res?.results ?? []).map(x => [x.trial, x]))
  return rows.map(r => {
    if (r.status !== 'completed') return r
    const x = g.get(r.trial)
    if (!x) return { ...r, graded: false, ungraded_reason: 'grader agent returned no row' }
    if (x.grader_error) {
      state.graderErrors += 1
      if (state.graderErrors >= MAX_GRADER_ERRORS) halt(`grader broken: ${state.graderErrors} grader errors, last: ${x.grader_error_detail ?? 'no detail'}`)
      return { ...r, graded: false, ungraded_reason: `grader_error: ${x.grader_error_detail ?? ''}` }
    }
    if (x.peeked) {
      state.voids.push({ cfg: r.cfg, ticket: r.ticket, trial: r.trial, evidence: x.peek_evidence ?? '' })
      halt(`answer key leak in ${r.cfg}:${r.ticket} trial ${r.trial}`)
      return { ...r, graded: true, voided: true, peek_evidence: x.peek_evidence }
    }
    return {
      ...r,
      graded: true,
      voided: false,
      category_ok: !!x.category_ok,
      priority_ok: !!x.priority_ok,
      pass: !!x.category_ok && !!x.priority_ok,
      blind_written: !!x.blind_written,
      blind_id: blindId(r.cfg, r.ticket, r.trial),
    }
  })
}

// ---------- Trials ----------
phase('Trials')
const firstPass = await pipeline(
  cells,
  async cell => ({ cell, rows: await runCell(cell, 1, TRIALS, 'Trials') }),
  async ({ cell, rows }) => ({ cell, rows: await gradeCell(cell, rows, 'Trials', 'main') })
)
const byCell = new Map(firstPass.map(x => [x.cell.id, { cell: x.cell, rows: x.rows }]))

// ---------- Top-up ----------
phase('Top-up')
const mixed = [...byCell.values()].filter(({ rows }) => {
  const ok = rows.filter(r => r.graded && !r.voided)
  const passes = ok.filter(r => r.pass).length
  return passes > 0 && passes < ok.length
})
log(`Top-up: ${mixed.length} mixed cells get up to ${TOPUP_MAX} extra trials each`)
if (mixed.length && TOPUP_MAX > 0 && !state.halted) {
  const extra = await pipeline(
    mixed.map(m => m.cell),
    async cell => ({ cell, rows: await runCell(cell, TRIALS + 1, TOPUP_MAX, 'Top-up') }),
    async ({ cell, rows }) => ({ cell, rows: await gradeCell(cell, rows, 'Top-up', 'topup') })
  )
  for (const x of extra) byCell.get(x.cell.id).rows.push(...x.rows.map(r => ({ ...r, topup: true })))
}
const allRows = [...byCell.values()].flatMap(x => x.rows)

// ---------- Judge ----------
phase('Judge')
const toJudge = shuffle(
  allRows.filter(r => r.graded && !r.voided && r.blind_written),
  SEED
)
const byBlind = new Map(toJudge.map(r => [r.blind_id, r]))
const batches = []
for (let i = 0; i < toJudge.length; i += JUDGE_BATCH) batches.push(toJudge.slice(i, i + JUDGE_BATCH).map(r => r.blind_id))
log(`Judge: ${toJudge.length} replies in ${batches.length} batches. The judge model is ${JUDGE_MODEL}, the same family as the agents under test, because no other family is available. Shared blind spots are possible.`)

await parallel(
  batches.map((ids, i) => async () => {
    const tag = String(i + 1).padStart(3, '0')
    if (!reserve('judge', EST_JUDGE_BATCH_USD, `batch-${tag}`)) return
    const res = await agent(
      `You judge the tone of customer support replies for SPE round ${ROUND}.
First read ${P.judge} and apply its rubric and scale exactly.
Then read only these files:
${ids.map(b => `- ${P.results}/blind/${b}.md`).join('\n')}
Do not read any other file. Do not try to work out which configuration wrote a reply.
Judge tone only. Code grades the labels elsewhere, so ignore label correctness.
Write your scores as JSON to ${P.results}/judge/batch-${tag}.json and return the same scores.`,
      { label: `judge batch ${tag}`, phase: 'Judge', schema: JUDGE_SCHEMA, model: JUDGE_MODEL }
    )
    settle(EST_JUDGE_BATCH_USD, 0, EST_JUDGE_BATCH_USD)
    for (const it of res?.items ?? []) {
      const r = byBlind.get(it.blind_id)
      if (r) {
        r.tone_score = it.tone_score
        r.tone_pass = !!it.tone_pass
        r.tone_reason = it.reason ?? ''
      }
    }
  })
)

// ---------- Synthesis ----------
phase('Synthesis')
function summarize(rows) {
  const done = rows.filter(r => r.status === 'completed' && r.graded && !r.voided)
  const judged = done.filter(r => r.tone_score != null)
  const perTicket = {}
  for (const r of done) (perTicket[r.ticket] ??= []).push(r.pass ? 1 : 0)
  const tok = r => (r.input_tokens ?? 0) + (r.output_tokens ?? 0)
  return {
    planned: rows.length,
    completed_graded: done.length,
    not_counted: {
      harness_error: rows.filter(r => r.status === 'harness_error').length,
      rate_limited: rows.filter(r => r.status === 'rate_limited').length,
      skipped: rows.filter(r => r.status === 'skipped').length,
      voided: rows.filter(r => r.voided).length,
      ungraded: rows.filter(r => r.status === 'completed' && !r.graded).length,
    },
    pass_rate: r3(mean(done.map(r => (r.pass ? 1 : 0)))),
    category_acc: r3(mean(done.map(r => (r.category_ok ? 1 : 0)))),
    priority_acc: r3(mean(done.map(r => (r.priority_ok ? 1 : 0)))),
    ticket_macro_pass_rate: r3(mean(Object.values(perTicket).map(mean))),
    tone_judged: judged.length,
    tone_pass_rate: r3(mean(judged.map(r => (r.tone_pass ? 1 : 0)))),
    tone_score_mean: r3(mean(judged.map(r => r.tone_score))),
    runtime_s_mean: r3(mean(done.map(r => r.runtime_s ?? 0))),
    runtime_s_median: r3(median(done.map(r => r.runtime_s ?? 0))),
    tool_calls_mean: r3(mean(done.map(r => r.tool_calls ?? 0))),
    tokens_mean: r3(mean(done.map(tok))),
    tool_errors_mean: r3(mean(done.map(r => r.tool_errors ?? 0))),
    trials_with_tool_error_rate: r3(mean(done.map(r => ((r.tool_errors ?? 0) > 0 ? 1 : 0)))),
    cost_usd_per_task_mean: r3(mean(done.map(r => r.cost_usd ?? 0))),
  }
}
// Primary numbers use only the planned trials, so top-up does not reweight mixed cells.
const primary = {}
const withTopup = {}
for (const cfg of CONFIGS) {
  const rows = allRows.filter(r => r.cfg === cfg)
  primary[cfg] = summarize(rows.filter(r => r.trial <= TRIALS))
  withTopup[cfg] = summarize(rows)
}
const summary = {
  round: ROUND,
  dry_run: !!ONLY,
  halted: state.halted,
  configs: CONFIGS,
  trials_per_cell: TRIALS,
  tickets: tickets.length,
  primary,
  with_topup: withTopup,
  topup_cells: mixed.map(m => m.cell.id),
  voids: state.voids,
  skipped: state.skipped,
  grader_errors: state.graderErrors,
  agents_used: state.agents,
  budget: {
    cap_usd: budget.cap,
    spent_usd: r3(budget.spent),
    measured_usd: r3(budget.measured),
    estimated_usd: r3(budget.estimated),
  },
  judge_note: `Judge model ${JUDGE_MODEL} is the same family as the agents under test.`,
}

const failures = allRows
  .filter(r => r.graded && !r.voided && (!r.pass || r.tone_pass === false))
  .map(r => ({
    trial_ref: `${r.cfg}:${r.ticket}#${r.trial}`,
    category_ok: r.category_ok,
    priority_ok: r.priority_ok,
    tone_pass: r.tone_pass ?? null,
    tone_reason: r.tone_reason ?? '',
    transcript: r.transcript_path,
    out_dir: r.out_dir,
  }))

const fa = await agent(
  `You do failure analysis for SPE round ${ROUND}. Here are the aggregate numbers:
${JSON.stringify({ primary, halted: state.halted }, null, 2)}

Here are the failed trials:
${JSON.stringify(failures, null, 2)}

